def tokenize(text):
    return text.split()

def toy_embed(text, max_tokens=8):
    tokens = tokenize(text)[:max_tokens]
    seed = sum(len(t) for t in tokens)
    return [(seed % 5) / 5, (seed % 7) / 7]

def chunk_by_tokens(text, max_tokens):
    tokens = tokenize(text)
    return [
        " ".join(tokens[i:i + max_tokens])
        for i in range(0, len(tokens), max_tokens)
    ]

def ingest_document(doc_id, text, index, max_tokens=8):
    for i, chunk_text in enumerate(chunk_by_tokens(text, max_tokens)):
        index[f"{doc_id}-chunk{i}"] = toy_embed(chunk_text, max_tokens=max_tokens)

index = {}
document = (
    "Vacation requests are reviewed by the team lead. "
    "Approval typically takes two business days. "
    "Requests submitted less than 48 hours before the requested date "
    "require director sign-off instead of team lead approval."
)
ingest_document("policy-1", document, index)
for key, vector in index.items():
    print(key, vector)

sections.body:
Recursive (sometimes called 'structure-aware') chunking fixes the worst of fixed-size chunking's blindness while keeping its core simplicity: instead of one flat character count, it tries a **prioritized list of separators**, from most-meaningful to least. Split on the biggest, most natural boundary first -- typically a blank line between paragraphs. If a resulting piece still exceeds the size budget, don't give up on structure entirely; recursively split *that* specific piece using the next separator down the list -- sentence-ending punctuation, and only as an absolute last resort, plain whitespace.

```python
def split_on(text, sep):
    return [p for p in text.split(sep) if p]

def recursive_chunk(text, max_size, separators):
    if len(text) <= max_size or not separators:
        return [text]
    sep, rest = separators[0], separators[1:]
    pieces = split_on(text, sep)
    if len(pieces) == 1:
        return recursive_chunk(text, max_size, rest)
    chunks, current = [], ""
    for piece in pieces:
        candidate = (current + sep + piece) if current else piece
        if len(candidate) <= max_size:
            current = candidate
        else:
            if current:
                chunks.append(current)
            if len(piece) > max_size:
                chunks.extend(recursive_chunk(piece, max_size, rest))
                current = ""
            else:
                current = piece
    if current:
        chunks.append(current)
    return chunks

doc = (
    "Paragraph one is short.\n\n"
    "Paragraph two is also fairly short and simple.\n\n"
    "Paragraph three is much longer and goes on for quite a while "
    "describing many details that would not normally fit into a "
    "small chunk size at all."
)
for chunk in recursive_chunk(doc, 60, ["\n\n", ". ", " "]):
    print(len(chunk), repr(chunk))
```

The first two paragraphs are short enough to survive as complete, untouched chunks. The third paragraph, at over 150 characters, is too long to survive the initial paragraph-level split intact -- so it recurses, falling back to splitting on `". "` (there isn't one, since it's a single sentence) and then on plain spaces, breaking it into three pieces that each respect the 60-character ceiling while still breaking on whole-word boundaries rather than mid-word. Nothing here is cutting inside a word the way naive fixed-size chunking would; the size budget is still enforced, but only after every higher-priority, more-natural boundary has been tried first.

